import pandas as pd,numpy as np,json,time
from sklearn.model_selection import train_test_split
from sklearn.metrics import roc_auc_score,average_precision_score,accuracy_score
from xgboost import XGBClassifier
out={}
a=pd.read_csv('/mnt/data/master_lead_data.csv');out['master_rows']=len(a);out['master_target']=a.initial_decision.value_counts().to_dict();a=a.dropna(subset=['emp_length']).copy();m={'< 1 year':0,'10+ years':10};m.update({f'{i} year'+('' if i==1 else 's'):i for i in range(1,10)});a['emp_length_years']=a.emp_length.map(m); X=a[['loan_amnt','dti','emp_length_years']];y=(a.initial_decision=='Accepted').astype(int);xt,xte,yt,yte=train_test_split(X,y,test_size=.15,random_state=42,stratify=y);xtr,xv,ytr,yv=train_test_split(xt,yt,test_size=.1765,random_state=42,stratify=yt);model=XGBClassifier(n_estimators=200,max_depth=6,learning_rate=.1,subsample=.8,colsample_bytree=.8,random_state=42,eval_metric='auc',n_jobs=4);model.fit(xtr,ytr);out['approval']={'train':len(xtr),'validation':len(xv),'test':len(xte),'validation_auc':float(roc_auc_score(yv,model.predict_proba(xv)[:,1])),'test_auc':float(roc_auc_score(yte,model.predict_proba(xte)[:,1])),'test_accuracy':float(accuracy_score(yte,model.predict(xte)))};print('APPROVAL',out['approval'],flush=True)
cols=['loan_status','loan_amnt','term','int_rate','installment','grade','sub_grade','emp_length','home_ownership','annual_inc','verification_status','purpose','dti','delinq_2yrs','fico_range_low','fico_range_high','inq_last_6mths','open_acc','pub_rec','revol_bal','revol_util','total_acc','initial_list_status','application_type','mort_acc','pub_rec_bankruptcies'];b=pd.read_csv('/mnt/data/accepted_sample.csv',usecols=cols,low_memory=False);out['accepted_rows']=len(b); statuses=['Fully Paid','Charged Off','Default','Does not meet the credit policy. Status:Fully Paid','Does not meet the credit policy. Status:Charged Off'];b=b[b.loan_status.isin(statuses)].copy();b['target_default']=b.loan_status.isin(['Charged Off','Default','Does not meet the credit policy. Status:Charged Off']).astype(int);out['completed_rows']=len(b);out['default_prevalence']=float(b.target_default.mean());b=b.drop(columns='loan_status');b['emp_length']=b.emp_length.fillna('Unknown');b['revol_util']=b.revol_util.fillna(b.revol_util.median());b['pub_rec_bankruptcies']=b.pub_rec_bankruptcies.fillna(0);b['mort_acc']=b.mort_acc.fillna(0);b['annual_inc']=b.annual_inc.fillna(b.annual_inc.median());b['term_months']=b.term.str.replace(' months','',regex=False).astype(int);b['grade_num']=b.grade.map(dict(zip('ABCDEFG',range(1,8))));b['fico_avg']=(b.fico_range_low+b.fico_range_high)/2;b=pd.get_dummies(b,columns=['home_ownership','verification_status','purpose','initial_list_status','application_type'],drop_first=True);b['emp_length_years']=b.emp_length.map({**m,'Unknown':-1});b=b.drop(columns=['term','grade','sub_grade','emp_length','fico_range_low','fico_range_high']); X=b.drop(columns='target_default');y=b.target_default;xt,xte,yt,yte=train_test_split(X,y,test_size=.15,random_state=42,stratify=y);xtr,xv,ytr,yv=train_test_split(xt,yt,test_size=.1765,random_state=42,stratify=yt);w=(ytr==0).sum()/(ytr==1).sum();model=XGBClassifier(n_estimators=300,max_depth=7,learning_rate=.05,subsample=.8,colsample_bytree=.8,random_state=42,scale_pos_weight=w,eval_metric='auc',n_jobs=4);model.fit(xtr,ytr);pv=model.predict_proba(xv)[:,1];pt=model.predict_proba(xte)[:,1];out['default']={'train':len(xtr),'validation':len(xv),'test':len(xte),'validation_auc':float(roc_auc_score(yv,pv)),'test_auc':float(roc_auc_score(yte,pt)),'test_average_precision':float(average_precision_score(yte,pt)),'test_accuracy':float(accuracy_score(yte,model.predict(xte)))};print('DEFAULT',out['default'],flush=True)
with open('/mnt/data/fintech_validation_metrics.json','w') as f:json.dump(out,f,indent=2)
